/**
 * Canonical signed messages. Must produce byte-identical strings to the Rust `obkit-wire` crate;
 * `test/vectors.json` (generated by Rust) pins both.
 */
export type Side = "buy" | "sell";
export type Tif = "gtc" | "ioc" | "fok" | "post_only";
export type Stp = "cancel_taker" | "cancel_maker" | "cancel_both";

export const MAX_SKEW_MS = 30_000;

export interface OrderMsg {
  account: string;
  market: string;
  side: Side;
  price: number | bigint;
  qty: number | bigint;
  tif: Tif;
  stp: Stp;
  clientId: number | bigint;
  tsMs: number;
}

const int = (n: number | bigint, what: string) => {
  const b = BigInt(n);
  if (b < 0n) throw new Error(`${what} must be non-negative`);
  return b.toString();
};

export function orderMessage(o: OrderMsg): string {
  return ["obkit-order-v1", o.account, o.market, o.side, int(o.price, "price"), int(o.qty, "qty"), o.tif, o.stp, int(o.clientId, "clientId"), int(o.tsMs, "ts")].join("|");
}

/** Exactly one of `orderId` / `clientId` non-zero. */
export function cancelMessage(account: string, market: string, orderId: number | bigint, clientId: number | bigint, tsMs: number): string {
  return ["obkit-cancel-v1", account, market, int(orderId, "orderId"), int(clientId, "clientId"), int(tsMs, "ts")].join("|");
}

export function cancelAllMessage(account: string, market: string | null, tsMs: number): string {
  return ["obkit-cancel-all-v1", account, market ?? "*", int(tsMs, "ts")].join("|");
}

/** Verified by the node and again on-chain by the settlement contract. */
export function withdrawMessage(contract: string, account: string, token: string, amount: bigint | string, nonce: number | bigint): string {
  return ["obkit-withdraw-v1", contract, account, token, int(BigInt(amount), "amount"), int(nonce, "nonce")].join("|");
}

export function authMessage(account: string, tsMs: number): string {
  return ["obkit-auth-v1", account, int(tsMs, "ts")].join("|");
}

export const validAccount = (s: string) => /^[a-z0-9._-]{2,64}$/.test(s);
export const validMarket = (s: string) => /^[A-Z0-9-]{3,32}$/.test(s);
